INSERT INTO documentos (coleccion, id, datos, orde) VALUES ('edicions', '2023', '{"numero":1,"ano":2023,"titulo":"I Feira da Sostibilidade","datas":"Abril de 2023","lugar":"IES Luís Seoane · Monte Porreiro, Pontevedra","estado":"pasada","resumo":"A edición pioneira. Impulsada polo colectivo Eco-Étika, uniu comunidade educativa, asociacións e comercio local arredor da sostibilidade.","corpo":"<p>A primeira Feira da Sostibilidade naceu da iniciativa do colectivo Eco-Étika, formado por alumnado do IES Luís Seoane. Converteu o centro nun espazo pioneiro en Galicia que uniu comunidades educativas, asociacións e comercio local arredor da sostibilidade e o consumo responsable.</p>","cifras":[],"fitos":["Impulsada por Eco-Étika","Premio Galicons-net"],"programa":[],"centros":["IES Luís Seoane"],"grupos":[{"titulo":"Organiza","entidades":["ies-luis-seoane"]},{"titulo":"Impulsa","entidades":["cidel-galicia"]}],"galeria":[],"videos":[],"documentos":[{"titulo":"Memoria I Edición"}],"prensa":[]}', 977);
INSERT INTO documentos (coleccion, id, datos, orde) VALUES ('edicions', '2024', '{"numero":2,"ano":2024,"titulo":"II Feira da Sostibilidade","datas":"Abril de 2024","lugar":"IES Luís Seoane · Monte Porreiro, Pontevedra","estado":"pasada","resumo":"Consolidación da rede. Incorpóranse a Universidade de Vigo, o IES de Poio e o IES Rafael Dieste, e hai stands do alumnado de varios centros.","corpo":"<p>A segunda edición consolidou a rede. Incorporáronse a Universidade de Vigo, o IES de Poio e o IES Rafael Dieste, e por primeira vez houbo stands do alumnado de varios centros e un debate público sobre consumismo e desinformación.</p>","cifras":[],"fitos":["Incorporación da Universidade de Vigo","Primeiros stands de varios centros","Debate público sobre consumismo e desinformación"],"programa":[],"centros":["IES Luís Seoane","IES de Poio","IES Rafael Dieste"],"grupos":[{"titulo":"Organiza","entidades":["ies-luis-seoane"]},{"titulo":"Impulsan","entidades":["cidel-galicia","universidade-de-vigo"]}],"galeria":[],"videos":[],"documentos":[{"titulo":"Memoria II Edición"}],"prensa":[]}', 976);
INSERT INTO documentos (coleccion, id, datos, orde) VALUES ('edicions', '2025', '{"numero":3,"ano":2025,"titulo":"III Feira da Sostibilidade","datas":"Abril de 2025","lugar":"IES Luís Seoane · Monte Porreiro, Pontevedra","estado":"pasada","resumo":"Expansión a 9 centros educativos de Galicia e 22 entidades colaboradoras. Comeza a liña de ciencia cidadá co Post-Growth Innovation Lab.","corpo":"<p>A terceira edición converteu a Feira nunha rede galega de innovación educativa. Participaron 9 centros educativos de Galicia e 22 entidades colaboradoras, e o CFR de Pontevedra aprobou o primeiro grupo de traballo intercentros.</p>\n<p>Nesta edición comezou a liña de ciencia cidadá co Post-Growth Innovation Lab da Universidade de Vigo, que converte o alumnado en investigador dos retos do seu territorio.</p>","cifras":[{"valor":"9","etiqueta":"centros educativos de Galicia"},{"valor":"22","etiqueta":"entidades colaboradoras"}],"fitos":["Inicio da liña de ciencia cidadá","Grupo de traballo intercentros aprobado polo CFR"],"programa":[],"centros":["IES Luís Seoane e 8 centros educativos de Galicia"],"grupos":[{"titulo":"Organiza","entidades":["ies-luis-seoane"]},{"titulo":"Impulsan","entidades":["cidel-galicia","universidade-de-vigo"]}],"galeria":[],"videos":[],"documentos":[{"titulo":"Memoria III Edición"}],"prensa":[]}', 975);
