INSERT INTO documentos (coleccion, id, datos, orde) VALUES ('edicions', '2026', '{"numero":4,"ano":2026,"titulo":"IV Feira da Sostibilidade","datas":"Abril de 2026","lugar":"IES Luís Seoane · Monte Porreiro, Pontevedra","estado":"pasada","resumo":"A máis grande ata o momento. 30 entidades e 13 centros educativos de Galicia, España e Europa, co I Foro de Desenvolvemento Local integrado na Feira.","corpo":"<p>A cuarta edición consolidou a Feira como referente galego de educación transformadora. Participaron 30 entidades e 13 centros educativos de Galicia, doutras comunidades autónomas e de Europa.</p>\n<p>No marco da Feira celebrouse o I Foro de Desenvolvemento Local, onde o alumnado do IES Luís Seoane presentou o estudo de ciencia cidadá sobre o patrón de consumo de alimentos en Pontevedra, desenvolvido co Post-Growth Innovation Lab da Universidade de Vigo: 587 enquisas recollidas en 6 zonas do municipio e propostas de axenda local para reducir a pegada de carbono.</p>","portada":"f-stand-artesania","portadaAlt":"Alumnado nun stand de artesanía na IV Feira da Sostibilidade","cifras":[{"valor":"1.127","etiqueta":"participantes directos estimados"},{"valor":"30","etiqueta":"entidades colaboradoras"},{"valor":"13","etiqueta":"centros (9 Galicia · 2 España · 2 Europa)"},{"valor":"120+","etiqueta":"alumnos e alumnas presentando nos stands"},{"valor":"528","etiqueta":"alumnado activo en obradoiros e dinámicas"},{"valor":"6.870+","etiqueta":"impacto indirecto estimado"}],"fitos":["I Foro de Desenvolvemento Local","Estudo de ciencia cidadá sobre o consumo de alimentos","30 entidades"],"programa":[],"centros":["IES Luís Seoane","IES de Poio","IES Rafael Dieste","IES Val da Asma","IES Chapela","IES Antón Alonso Ríos","IES Rego de Trabe","CEP Marcos da Portela","EEI Fina Casalderey","CIPF A Xunqueira","2 centros doutras comunidades autónomas","2 centros europeos (Erasmus+)"],"grupos":[{"titulo":"Organiza","entidades":["ies-luis-seoane"]},{"titulo":"Impulsan","entidades":["cidel-galicia","universidade-de-vigo"]},{"titulo":"Colaboran","entidades":["oxfam-intermon","adega","cogami","solidariedade-internacional","afectados-a57","ec4rural","cruz-vermella","feitoria-verde","galicia-ambiental","sig-comercio-xusto","casa-grande-de-xanceda","o-colmenar-de-sara"]}],"galeria":[{"imaxe":"f-stand-2","alt":"Stand número 2 da Feira con materiais do alumnado"},{"imaxe":"f-stand-alumnas","alt":"Alumnas explicando o seu stand a outras visitantes"},{"imaxe":"f-xogo-inclusivo","alt":"Nenas e nenos xogando a un xogo inclusivo no chan"},{"imaxe":"f-stand-4-ruleta","alt":"Stand con ruleta de xogo e voluntariado atendendo"},{"imaxe":"f-exposicion-carteis","alt":"Exposición de carteis no corredor"},{"imaxe":"f-stand-15","alt":"Posto 15 do alumnado con produtos de deseño propio"},{"imaxe":"f-obradoiro-mans","alt":"Mans traballando nun obradoiro"},{"imaxe":"f-charla-auditorio","alt":"Charla no salón de actos ante o alumnado"},{"imaxe":"f-exposicion-gravados","alt":"Panel cunha exposición de gravados en branco e negro"},{"imaxe":"f-stand-sociocultural","alt":"Stand de La Sociocultural con libros e carteis"},{"imaxe":"f-xogo-mesa","alt":"Xogo de mesa educativo creado polo alumnado"},{"imaxe":"f-alumnado-presenta-investigacion","alt":"Alumnado presentando os resultados da investigación cidadá"}],"videos":[],"documentos":[{"titulo":"Memoria IV Edición (en breve)"}],"prensa":[{"medio":"Diario de Pontevedra"},{"medio":"Pontevedra Viva"}]}', 974);
