INSERT INTO documentos (coleccion, id, datos, orde) VALUES ('edicions', '2027', '{"numero":5,"ano":2027,"titulo":"V Feira da Sostibilidade","lema":"Eco-Étika en acción","datas":"28, 29 e 30 de abril de 2027","lugar":"IES Luís Seoane · Monte Porreiro, Pontevedra","estado":"proxima","resumo":"Tres xornadas abertas de stands, obradoiros, charlas-foro, demostracións, xogos e escape rooms. Nesta edición conflúen os 10 microproxectos Eco-Étika, o II Foro de Desenvolvemento Local e a I Conferencia COOPEDUGAL.","corpo":"<p>A quinta edición da Feira da Sostibilidade dá continuidade ás catro anteriores como espazo aberto de participación, intercambio e sensibilización arredor dos retos ecosociais e das alternativas para abordalos.</p>\n<p>Celébrase nun centro cunha comunidade educativa de arredor de 1.460 persoas e reúne centros educativos, a Universidade de Vigo, entidades sociais, ONGD, administracións, empresas e outras iniciativas do territorio. O protagonismo é do alumnado e do profesorado, que presentan, dinamizan e comparten os coñecementos, experiencias e propostas construídos durante o curso.</p>\n<p>Esta edición forma parte de <strong>SENDA 2030. Xeración Eco-Étika</strong>, un proxecto de Educación para o Desenvolvemento e a Cidadanía Global que conecta ciencia cidadá, práctica docente e participación xuvenil, con experiencias e voces de República Dominicana e outros territorios de América Latina.</p>","portada":"f-multitude-corredor","portadaAlt":"Corredor do IES Luís Seoane cheo de xente durante a Feira da Sostibilidade","cifras":[{"valor":"3","etiqueta":"xornadas"},{"valor":"~1.000","etiqueta":"participacións previstas"},{"valor":"13+","etiqueta":"centros educativos con papel activo"},{"valor":"10","etiqueta":"microproxectos Eco-Étika do alumnado"}],"fitos":["II Foro de Desenvolvemento Local","I Conferencia COOPEDUGAL","Microproxectos Eco-Étika. Pensa. Actúa.","Voces do Sur Global"],"programa":[{"dia":"Programa en preparación","actividades":[{"titulo":"Stands e microproxectos do alumnado","descricion":"Os 10 microproxectos Eco-Étika presentados e dinamizados polo alumnado e o profesorado dos centros participantes."},{"titulo":"Investigacións de ciencia cidadá no rural","descricion":"Os 6 centros rurais vinculados a Postgrowth S.A.:Rural comparten as súas investigacións sobre a transición ecolóxica xusta."},{"titulo":"II Foro de Desenvolvemento Local","descricion":"O rural ante a transición ecolóxica xusta: mesas de deliberación entre alumnado, profesorado e actores do territorio, en colaboración co Concello de Pontevedra."},{"titulo":"I Conferencia COOPEDUGAL","descricion":"Dúas xornadas de relatorios, experiencias e o espazo «O Local dende o Sur», vinculadas á Feira."},{"titulo":"Obradoiros, charlas-foro, xogos e escape rooms","descricion":"Propostas de centros, entidades sociais, ONGD, universidade e iniciativas do territorio."}]}],"centros":["IES Luís Seoane (Pontevedra)","Centros participantes en SENDA 2030 das catro provincias","6 centros rurais de Postgrowth S.A.:Rural"],"grupos":[{"titulo":"Organiza","entidades":["ies-luis-seoane"]},{"titulo":"Impulsan","entidades":["cidel-galicia","universidade-de-vigo"]},{"titulo":"Co apoio de","entidades":["cooperacion-galega"]},{"titulo":"Colaboran","entidades":["concello-de-pontevedra","cfr-pontevedra"]}],"galeria":[],"videos":[],"documentos":[],"prensa":[],"proxecto":"senda-2030"}', 973);
