INSERT INTO documentos (coleccion, id, datos, orde) VALUES ('noticias', '2026-04-cocinando-sostibilidade', '{"titulo":"Cociñando sostibilidade coas primeiras idades","data":"2026-04-15","resumo":"O alumnado máis novo pasou pola cociña para aprender a cociñar con produto de proximidade e sen desperdicio.","edicion":"2026","imaxe":"f-obradoiro-cocina","imaxeAlt":"Obradoiro de cociña sostible coas primeiras idades","corpo":"<p>Na IV Feira da Sostibilidade, o alumnado máis novo participou nun obradoiro de cociña con produto de proximidade e sen desperdicio.</p>","borrador":false}', 0);
