INSERT INTO documentos (coleccion, id, datos, orde) VALUES ('noticias', '2026-04-colmenar-de-sara', '{"titulo":"O Colmenar de Sara: mel de Galicia con IXP","data":"2026-04-15","resumo":"Charla sobre a Indicación Xeográfica Protexida do mel galego e o papel das pequenas produtoras no territorio.","edicion":"2026","imaxe":"f-charla-mel","imaxeAlt":"Charla sobre o Colmenar de Sara no salón de actos","corpo":"<p>Na IV Feira da Sostibilidade, O Colmenar de Sara achegou ao alumnado a Indicación Xeográfica Protexida do mel de Galicia e o papel das pequenas produtoras no territorio.</p>","borrador":false}', 0);
