INSERT INTO documentos (coleccion, id, datos, orde) VALUES ('noticias', '2026-04-posto-15', '{"titulo":"Posto 15: economía circular en acción","data":"2026-04-15","resumo":"Un dos postos do alumnado, con produtos de deseño propio e venda directa, mostrou a economía circular feita realidade.","edicion":"2026","imaxe":"f-posto-15","imaxeAlt":"Posto 15 do alumnado na Feira da Sostibilidade","corpo":"<p>No posto 15 da IV Feira da Sostibilidade, o alumnado presentou produtos de deseño propio con venda directa: a economía circular levada á práctica.</p>","borrador":false}', 0);
INSERT INTO documentos (coleccion, id, datos, orde) VALUES ('noticias', '2026-10-20-senda-2030-cooperacion-galega', '{"titulo":"SENDA 2030 recibe o apoio da Cooperación Galega","data":"2026-10-20","resumo":"O proxecto SENDA 2030. Xeración Eco-Étika, de CIDEL Galicia e a Universidade de Vigo, foi seleccionado na convocatoria de educación para o desenvolvemento e a cidadanía global. A V Feira da Sostibilidade será o seu grande espazo de encontro.","edicion":"2027","imaxe":"f-alumnado-presenta-investigacion","imaxeAlt":"Alumnado presentando os resultados dunha investigación de ciencia cidadá","corpo":"<p>A Xunta de Galicia, a través da Cooperación Galega, resolveu a convocatoria de proxectos de educación para o desenvolvemento e a cidadanía global 2026. Entre os proxectos subvencionados está <strong>SENDA 2030. Xeración Eco-Étika: Construíndo cidadanía global dende as aulas a través da ciencia cidadá e a participación</strong>, presentado pola agrupación de CIDEL Galicia e a Universidade de Vigo.</p>\n<p>O proxecto, que conta co IES Luís Seoane como aliado educativo, implicará ata 16 centros educativos galegos durante o curso 2026–2027: formación e laboratorio docente, investigacións de ciencia cidadá, a campaña «Eco-Étika: Dálle a volta», encontros con docentes e mocidade de América Latina e dez microproxectos protagonizados polo alumnado.</p>\n<p>Todo ese traballo confluirá na <strong>V Feira da Sostibilidade</strong>, os días 28, 29 e 30 de abril de 2027 no IES Luís Seoane, xunto co II Foro de Desenvolvemento Local e a I Conferencia COOPEDUGAL.</p>","borrador":false}', 0);
INSERT INTO documentos (coleccion, id, datos, orde) VALUES ('recursos', 'axenda-politica-local', '{"titulo":"Axenda política local para a transición ecolóxica xusta","tipo":"estudo","resumo":"Proposta de axenda política para a transición ecolóxica xusta en Pontevedra, elaborada polo alumnado no proxecto de ciencia cidadá Postgrowth S.A.","temas":["Territorio","Transición ecolóxica","Ciencia cidadá"],"ods":[11,13],"autoria":"Alumnado participante en Postgrowth S.A. · Universidade de Vigo","licenza":"CC BY-SA 4.0","corpo":"<p>Resultado do proxecto de ciencia cidadá Postgrowth S.A.: propostas do alumnado para a política local.</p>"}', 0);
INSERT INTO documentos (coleccion, id, datos, orde) VALUES ('recursos', 'estudo-consumo-alimentos-pontevedra', '{"titulo":"Estudo de ciencia cidadá: patrón de consumo de alimentos en Pontevedra","tipo":"estudo","resumo":"O alumnado do IES Luís Seoane recolleu 587 enquisas en 6 zonas de Pontevedra e analizou as emisións de CO₂ asociadas ao consumo alimentario, co Post-Growth Innovation Lab da Universidade de Vigo.","edicion":"2026","temas":["Alimentación","Cambio climático","Ciencia cidadá"],"ods":[2,12,13],"imaxe":"f-alumnado-presenta-investigacion","imaxeAlt":"Alumnado presentando o estudo de ciencia cidadá","autoria":"IES Luís Seoane · Universidade de Vigo · Curso 2025–2026","licenza":"CC BY-SA 4.0","corpo":"<p>Proxecto de ciencia cidadá co-creado co Post-Growth Innovation Lab da Universidade de Vigo e financiado polo Ministerio de Dereitos Sociais, Consumo e Axenda 2030. Os resultados presentáronse no I Foro de Desenvolvemento Local da IV Feira.</p>\n<p><strong>587</strong> enquisas recollidas · <strong>454</strong> válidas · <strong>6</strong> zonas do municipio.</p>\n<h2>Cinco conclusións</h2>\n<ol>\n<li>O consumo de carne ten o maior impacto nas emisións de gases de efecto invernadoiro.</li>\n<li>A sensibilización e a educación son clave para patróns máis sostibles.</li>\n<li>Hai marxe para a autoprodución e o comercio local como alternativa.</li>\n<li>A ciencia cidadá implica aprendizaxes metodolóxicas reais e colectivas.</li>\n<li>Identificáronse vías de acción local: mercados, hortas e etiquetaxe.</li>\n</ol>"}', 0);
INSERT INTO documentos (coleccion, id, datos, orde) VALUES ('recursos', 'fake-news-climaticas', '{"titulo":"Fake News Climáticas","tipo":"xogo","resumo":"Recurso interactivo para detectar e desmontar desinformación sobre o cambio climático, deseñado e validado polo alumnado en colaboración co profesorado.","temas":["Cambio climático","Desinformación"],"ods":[13],"autoria":"Alumnado do IES Luís Seoane","licenza":"CC BY-SA 4.0","corpo":"<p>Unha ferramenta para aprender a recoñecer e desmontar a desinformación climática.</p>"}', 0);
INSERT INTO documentos (coleccion, id, datos, orde) VALUES ('recursos', 'naturpoly', '{"titulo":"Naturpoly","tipo":"xogo","resumo":"Xogo de mesa creado polo alumnado para concienciar sobre o impacto da fast fashion, coa mecánica do Monopoly adaptada á educación para a sostibilidade.","temas":["Consumo responsable","Moda sostible"],"ods":[12],"imaxe":"f-xogo-mesa","imaxeAlt":"Taboleiro dun xogo educativo creado polo alumnado","autoria":"Alumnado do IES Luís Seoane","licenza":"CC BY-SA 4.0","corpo":"<p>Un xogo de mesa para falar do impacto social e ambiental da moda rápida xogando.</p>"}', 0);
INSERT INTO documentos (coleccion, id, datos, orde) VALUES ('recursos', 'obradoiro-xabons-naturais', '{"titulo":"Obradoiro de xabóns naturais","tipo":"obradoiro","resumo":"Obradoiro de economía circular con tintes e xabóns naturais. Material didáctico completo para replicalo noutros centros educativos.","temas":["Economía circular","Consumo responsable"],"ods":[12],"imaxe":"f-obradoiro-mans","imaxeAlt":"Mans traballando nun obradoiro","licenza":"CC BY-SA 4.0","corpo":"<p>Un obradoiro práctico para aprender economía circular facendo.</p>"}', 0);
INSERT INTO documentos (coleccion, id, datos, orde) VALUES ('recursos', 'podcast-eco-etika', '{"titulo":"Podcast Eco-Étika","tipo":"podcast","resumo":"Serie de podcast producida polo alumnado sobre sostibilidade, consumo responsable e cidadanía activa, con entrevistas e reflexións propias.","temas":["Consumo responsable","Cidadanía activa"],"ods":[4,12],"autoria":"Alumnado do IES Luís Seoane","licenza":"CC BY-SA 4.0","corpo":"<p>O alumnado entrevista, debate e reflexiona en voz alta sobre os retos da Axenda 2030.</p>"}', 0);
INSERT INTO documentos (coleccion, id, datos, orde) VALUES ('proxectos', 'senda-2030', '{"titulo":"SENDA 2030. Xeración Eco-Étika: Construíndo cidadanía global dende as aulas a través da ciencia cidadá e a participación","nomeCurto":"SENDA 2030","edicion":"2027","resumo":"Proxecto de Educación para o Desenvolvemento e a Cidadanía Global que mellora a capacidade da comunidade educativa galega para xerar procesos de acción colectiva ante os retos ecosociais, conectando ciencia cidadá, práctica docente, participación xuvenil e cooperación.","financiamento":"Proxecto financiado pola Xunta de Galicia (Cooperación Galega) na convocatoria de proxectos de educación para o desenvolvemento e a cidadanía global 2026 (expediente PR804A-2026-00000029-00).","entidades":["cidel-galicia","universidade-de-vigo","ies-luis-seoane","cooperacion-galega"],"cifras":[{"valor":"16","etiqueta":"centros educativos"},{"valor":"350+","etiqueta":"alumnos e alumnas"},{"valor":"30+","etiqueta":"docentes"},{"valor":"10","etiqueta":"microproxectos Eco-Étika"}],"actividades":[{"codigo":"A1.1.1","resultado":"R1.1 · Investigación e análise crítica","titulo":"Obradoiros de cidadanía global e comunicación","descricion":"Seis obradoiros en centros rurais nos que o alumnado interpreta as evidencias das súas investigacións de ciencia cidadá desde unha mirada global e elabora publicacións de comunicación."},{"codigo":"A1.1.2","resultado":"R1.1 · Investigación e análise crítica","titulo":"Encontro aberto da Rede de Ciencia Cidadá","descricion":"Espazo de intercambio entre comunidade educativa, universidade, ONGD e administracións sobre ciencia cidadá e educación para a cidadanía global."},{"codigo":"A1.1.3","resultado":"R1.1 · Investigación e análise crítica","titulo":"Investigación transversal ciencia cidadá–EpDCG","descricion":"Como pode a ciencia cidadá contribuír á educación para a cidadanía global? Un informe aberto con resultados e recomendacións prácticas para os centros."},{"codigo":"A1.1.4","resultado":"R1.1 · Investigación e análise crítica","titulo":"I Conferencia COOPEDUGAL","descricion":"Dúas xornadas no IES Luís Seoane, vinculadas á Feira, con relatorios, experiencias do alumnado e o espazo «O Local dende o Sur»."},{"codigo":"A1.2.1","resultado":"R1.2 · Práctica docente","titulo":"Formación aplicada en EpDCG e análise local-global","descricion":"Nove horas de formación para o profesorado dos centros participantes, con participación directa de persoas e organizacións do Sur Global."},{"codigo":"A1.2.2","resultado":"R1.2 · Práctica docente","titulo":"Laboratorio docente","descricion":"Deseño, experimentación nas aulas e revisión entre pares de propostas educativas local-global."},{"codigo":"A1.2.3","resultado":"R1.2 · Práctica docente","titulo":"Campaña «Eco-Étika: Dálle a volta»","descricion":"Que hai detrás de…? Narrativas do alumnado sobre os retos ecosociais en vídeos, podcast, ilustracións ou infografías."},{"codigo":"A1.2.4","resultado":"R1.2 · Práctica docente","titulo":"Encontros local-global: aulas en diálogo","descricion":"Tres encontros en liña entre docentes de Galicia e do Sur Global, coa participación do Distrito Educativo de República Dominicana."},{"codigo":"A1.2.5","resultado":"R1.2 · Práctica docente","titulo":"Espazo de recursos e experiencias local-global","descricion":"Un espazo dixital para o profesorado, organizado en itinerarios temáticos e preguntas educativas, con recursos abertos e reutilizables."},{"codigo":"A1.3.1","resultado":"R1.3 · Deliberación e acción colectiva","titulo":"Microproxectos Eco-Étika. Pensa. Actúa.","descricion":"Dez microproxectos protagonizados polo alumnado, que pasan da análise dun reto da súa contorna á acción e se presentan na Feira."},{"codigo":"A1.3.2","resultado":"R1.3 · Deliberación e acción colectiva","titulo":"II Foro de Desenvolvemento Local","descricion":"O rural ante a transición ecolóxica xusta. Mesas de deliberación entre alumnado, profesorado e actores do territorio, no marco da Feira."},{"codigo":"A1.3.3","resultado":"R1.3 · Deliberación e acción colectiva","titulo":"V Feira da Sostibilidade","descricion":"Tres xornadas abertas, 28–30 de abril de 2027, no IES Luís Seoane."},{"codigo":"A1.3.4","resultado":"R1.3 · Deliberación e acción colectiva","titulo":"Eco-Étika Conecta: rede xuvenil local-global","descricion":"Alumnado de centros galegos en diálogo con mozas e mozos de República Dominicana, Arxentina e outros territorios de América Latina."},{"codigo":"A1.3.5","resultado":"R1.3 · Deliberación e acción colectiva","titulo":"Comunicación crítica para a transformación social","descricion":"Alfabetización mediática e radioteatro a partir de contidos científicos da revista T·I·A·S – This Is Also Science."},{"codigo":"A1.3.6","resultado":"R1.3 · Deliberación e acción colectiva","titulo":"SENDA Aberta: sistematización e transferencia","descricion":"Un documental e a guía «Así fixemos SENDA» para que outros centros poidan adaptar a experiencia."}],"subtitulo":"Xeración Eco-Étika","corpo":"<p>SENDA 2030 é unha proposta de Educación para o Desenvolvemento e a Cidadanía Global promovida en agrupación por <strong>CIDEL Galicia</strong> e a <strong>Universidade de Vigo</strong> (Post-Growth Innovation Lab), co <strong>IES Luís Seoane</strong> como aliado educativo estratéxico.</p>\n<p>O proxecto propón que as aulas funcionen como espazos de investigación, aprendizaxe crítica, diálogo entre territorios e participación cidadá: <strong>investigar para comprender</strong>, <strong>contrastar o local co global</strong> para interpretar causas, dereitos, desigualdades e interdependencias, e <strong>transformar as aprendizaxes</strong> en capacidade de deliberación, proposta e acción.</p>\n<p>A intervención implica ata 16 centros educativos de Galicia: 10 no itinerario educativo principal e 6 centros rurais vinculados a Postgrowth S.A.:Rural. A V Feira da Sostibilidade é o grande espazo de encontro onde converxen os seus procesos.</p>"}', 0);
INSERT INTO documentos (coleccion, id, datos, orde) VALUES ('paxinas', 'inicio', '{"heroEtiqueta":"#AFeira · IES Luís Seoane · Pontevedra","heroTitulo":"A Feira non son dous días.","heroDestaque":"É un movemento.","heroTexto":"Dende 2023, a Feira da Sostibilidade converte o IES Luís Seoane nun laboratorio aberto onde o alumnado investiga, actúa e constrúe cidadanía crítica xunto a centros educativos, universidade e entidades sociais.","heroImaxe":"f-multitude-corredor","heroImaxeAlt":"Corredor do IES Luís Seoane cheo de xente durante a Feira","cifras":[{"valor":"4","etiqueta":"edicións celebradas"},{"valor":"+1.000","etiqueta":"persoas participantes por edición"},{"valor":"30","etiqueta":"entidades colaboradoras na IV edición"},{"valor":"13","etiqueta":"centros de Galicia, España e Europa"}],"edicionsTitulo":"Cada edición suma.","edicionsTexto":"A Feira é un proceso vivo que medra cada curso: máis centros, máis entidades e máis proxectos do alumnado.","cita":"O futuro non se explica.","citaDestaque":"Constrúese.","ecosistemaTitulo":"Unha rede que multiplica o impacto.","ecosistemaTexto":"Entidades sociais, ONGD, cooperativas, administracións e iniciativas do territorio que fan a Feira posible.","ecosistemaEntidades":["oxfam-intermon","adega","cogami","solidariedade-internacional","afectados-a57","ec4rural","cruz-vermella","feitoria-verde","galicia-ambiental","sig-comercio-xusto","casa-grande-de-xanceda","o-colmenar-de-sara"],"participaTitulo":"Non veñas só mirar. Participa.","participaTexto":"Centros educativos, entidades, empresas e medios: hai moitas formas de formar parte da Feira."}', 0);
INSERT INTO documentos (coleccion, id, datos, orde) VALUES ('paxinas', 'a-feira', '{"heroEtiqueta":"FeiraLab · Xeración Eco-Étika","heroTitulo":"Máis ca unha feira.","heroDestaque":"Un laboratorio permanente.","heroTexto":"A Feira é o momento no que meses de investigación, acción e construción colectiva de cidadanía crítica se fan visibles para toda a comunidade. Detrás hai un laboratorio de innovación educativa que traballa durante todo o curso.","heroImaxe":"f-stand-alumnas","heroImaxeAlt":"Alumnas explicando o seu stand na Feira","introTitulo":"E se un instituto puidese cambiar o mundo?","introCorpo":"<p>A Feira da Sostibilidade «Pensa, consume e actúa» naceu da iniciativa do colectivo <strong>Eco-Étika</strong>, formado por alumnado do IES Luís Seoane de Pontevedra. O <strong>IES Luís Seoane</strong> organízaa, e <strong>CIDEL Galicia</strong> e o <strong>Post-Growth Innovation Lab da Universidade de Vigo</strong> impúlsana e apóiana.</p><p>O instituto, no barrio de Monte Porreiro, abre as súas portas cada primavera a centros educativos, universidade, entidades sociais, administracións e veciñanza. O alumnado non presenta só resultados: comparte o que investigou, dinamiza actividades e constrúe propostas para o seu territorio.</p>","introImaxe":"f-alumnado-presenta-investigacion","introImaxeAlt":"Alumnado presentando os resultados dunha investigación cidadá","metodoloxiasTitulo":"Tres metodoloxías que se retroalimentan.","metodoloxias":[{"sigla":"ABP","nome":"Aprendizaxe Baseada en Proxectos","lema":"Investigar para comprender","texto":"O alumnado deseña e executa proxectos de investigación interdisciplinar sobre retos da Axenda 2030, conectando saberes científicos, sociais e artísticos."},{"sigla":"ApS","nome":"Aprendizaxe Servizo · CIDEL Galicia","lema":"Actuar para transformar","texto":"O eixo que une aprendizaxe e acción comunitaria: o alumnado pon o seu coñecemento ao servizo da comunidade, con rede internacional con colectivos de Galicia e América Latina."},{"sigla":"CC","nome":"Ciencia cidadá · Post-Growth Innovation Lab","lema":"Investigar con rigor e impacto real","texto":"Co acompañamento científico da Universidade de Vigo, o alumnado convértese en investigador activo e conecta o local —o barrio de Monte Porreiro— co global."}],"linhasTitulo":"Proxectos que moven o mundo.","linhasTexto":"O alumnado investiga en liñas temáticas conectadas cos ODS que se desenvolven ao longo do curso e culminan na Feira.","linhas":[{"titulo":"Clima, enerxía e transición ecolóxica","texto":"Cambio climático, consumo enerxético e transición xusta: datos reais, alternativas e comunicación á comunidade.","ods":"ODS 7 · ODS 13"},{"titulo":"Consumo responsable e moda sostible","texto":"O impacto da fast fashion e do consumismo, xogos educativos como Naturpoly e obradoiros de economía circular.","ods":"ODS 12"},{"titulo":"Xustiza global e cooperación internacional","texto":"Dereitos humanos, desigualdade e solidariedade internacional, en colaboración con Oxfam Intermón e SIG Comercio Xusto.","ods":"ODS 10 · ODS 16"},{"titulo":"Igualdade de xénero e diversidade","texto":"Investigación e acción sobre fendas de xénero, diversidade e inclusión, co proxecto NeoFem e o Comité UNESCO do centro.","ods":"ODS 5"},{"titulo":"Territorio, barrio e identidade local","texto":"Monte Porreiro como laboratorio social: mapeo comunitario e axendas políticas locais.","ods":"ODS 11"},{"titulo":"Saúde, benestar e alimentación sostible","texto":"Alimentación ecolóxica, hortas escolares, saúde mental e benestar, con entidades como Casa Grande de Xanceda e Feitoria Verde.","ods":"ODS 2 · ODS 3"}],"premiosTitulo":"Premios autonómicos de innovación educativa.","premios":[{"ano":"2022 · 2023","texto":"Premio Galicons-net de Innovación Educativa en Consumo Responsable (Xunta de Galicia)"},{"ano":"2024","texto":"III Premio Galego de Educación para o Desenvolvemento e a Cidadanía Global, á experiencia de Eco-Étika e o IES Luís Seoane"}]}', 0);
INSERT INTO documentos (coleccion, id, datos, orde) VALUES ('paxinas', 'participa', '{"heroTitulo":"Non veñas só mirar.","heroDestaque":"Participa.","heroTexto":"A Feira constrúese entre moitas mans. Centros educativos, entidades, empresas, administracións e medios: atopa o teu xeito de formar parte da V edición.","datas":[{"data":"Xa","texto":"Inscricións abertas para centros e entidades"},{"data":"28–30 abril 2027","texto":"V Feira da Sostibilidade no IES Luís Seoane (Pontevedra)"}],"perfis":[{"id":"centro","titulo":"Centros educativos","texto":"Trae á Feira o que investigou e creou o teu alumnado. Os centros participantes en SENDA 2030 contan con acompañamento durante o curso.","accions":["Presentar un stand ou un microproxecto do alumnado","Dinamizar un obradoiro, xogo ou demostración","Participar no II Foro de Desenvolvemento Local","Visitar a Feira cun grupo"],"boton":"Inscribir o meu centro"},{"id":"entidade","titulo":"Entidades, colectivos e ONGD","texto":"Asociacións, cooperativas, ONGD e iniciativas do territorio que traballan pola sostibilidade, a cidadanía global e a xustiza social.","accions":["Ter un stand coas vosas propostas","Organizar un obradoiro ou unha charla-foro","Sumarvos ás mesas do Foro de Desenvolvemento Local"],"boton":"Propoñer a nosa participación"},{"id":"empresa","titulo":"Empresas e administracións","texto":"Colabora coa Feira achegando experiencias, recursos ou espazos de diálogo arredor da sostibilidade e a economía local.","accions":["Compartir experiencias de economía local e sostible","Apoiar con recursos ou materiais","Participar nos espazos de diálogo co alumnado"],"boton":"Ofrecer colaboración"},{"id":"prensa","titulo":"Prensa e medios","texto":"Información, imaxes e persoas de contacto para cubrir a Feira e os proxectos do alumnado.","accions":["Solicitar información e entrevistas","Acreditarse para as xornadas da Feira"],"boton":"Contactar como medio"}],"formularioTitulo":"Cóntanos como queres participar.","formularioTexto":"Enche o formulario e porémonos en contacto contigo. Só usaremos os teus datos para organizar a participación na Feira.","graciasTitulo":"Grazas! Recibimos a túa mensaxe.","graciasTexto":"Porémonos en contacto contigo nos próximos días."}', 0);
INSERT INTO documentos (coleccion, id, datos, orde) VALUES ('paxinas', 'aviso-legal', '{"corpo":"<h2>Titularidade</h2><p>Esta web divulga a Feira da Sostibilidade do IES Luís Seoane (Pontevedra) e os proxectos educativos vinculados. Organiza o IES Luís Seoane, e impulsan CIDEL Galicia e a Universidade de Vigo.</p><h2>Privacidade</h2><p>Esta web non usa cookies de seguimento. Os datos que envías a través dos formularios de Participa só se usan para organizar a túa participación na Feira, non se ceden a terceiros e elimínanse cando deixan de ser necesarios. Podes pedir que se consulten, corrixan ou eliminen escribindo ás entidades organizadoras.</p><p>As tipografías cárganse desde Google Fonts. As ligazóns a servizos externos (Instagram, plataformas de vídeo) réxense polas políticas desas plataformas.</p><h2>Imaxes de menores</h2><p>As imaxes nas que aparece alumnado publícanse coa autorización correspondente dos centros educativos. Se apareces nunha imaxe e queres que se retire, contacta co IES Luís Seoane e retirarémola.</p><h2>Licenza dos contidos</h2><p>Salvo indicación contraria, os textos e recursos desta web publícanse baixo licenza <a href=\"https://creativecommons.org/licenses/by-sa/4.0/deed.gl\">Creative Commons Recoñecemento-CompartirIgual 4.0 (CC BY-SA 4.0)</a>. Os logotipos pertencen ás súas respectivas entidades.</p>"}', 0);
INSERT INTO documentos (coleccion, id, datos, orde) VALUES ('axustes', 'xeral', '{"nome":"Feira da Sostibilidade","lema":"Pensa, consume e actúa","descricion":"A Feira da Sostibilidade do IES Luís Seoane (Pontevedra): un movemento educativo de alumnado, profesorado, universidade e entidades sociais arredor dos retos ecosociais e da cidadanía global.","edicionActual":"2027","instagram":"https://www.instagram.com/feiradasostibilidade","instagramUsuario":"@feiradasostibilidade","webIes":"https://iesluisseoane.org/","pe":{"texto":"Pensa, consume e actúa. Un movemento educativo nacido no IES Luís Seoane de Pontevedra a partir do colectivo Eco-Étika.","grupos":[{"titulo":"Organiza","entidades":["ies-luis-seoane"]},{"titulo":"Impulsan","entidades":["cidel-galicia","universidade-de-vigo"]},{"titulo":"Co apoio de","entidades":["cooperacion-galega"],"nota":"V Feira · proxecto SENDA 2030"}]}}', 0);
